const DADOS = {"armadilhas":{"agulha":{"nome":"Agulha com Peçonha (Entrada B)","onde":"Fechadura da Entrada B","nd":"1/4","det":"Investigação 20 ou Percepção 25","des":"Ladinagem 25 (Ofício [engenhoqueiro] substitui)","efeito":"Perda de 1d12 PV por rodada durante 3 rodadas; Fortitude CD 20 reduz para 1 rodada. Arrombar a fechadura é Ladinagem 25 (não existe chave). Rearma em 1d4 dias, com mecanismos novos; o Templo só tem mana para mais 1d6 iterações do veneno.","res":["fort",20,"uma"],"perda":"1d12","rodadas":3,"ic":"icons/svg/poison.svg"},"pendulo":{"nome":"Pêndulo de Teto","onde":"Nível 1, Sala 3 (Altar e Oferendas)","nd":1,"det":"Investigação 25","des":"Ladinagem 20","efeito":"1d12+10 de corte; Reflexos CD 25 evita. Dispara ao mexer nos tesouros ou no altar.","res":["refl",25,"evita"],"dano":"1d12+10[corte]","ic":"icons/svg/sword.svg"},"teto":{"nome":"Teto Esmagador","onde":"Nível 1, Sala 7 (Antessala do Mecanismo de Segurança)","nd":4,"det":"Investigação 20","des":"Ladinagem 20","ruido":5,"efeito":"8d6 de impacto numa área de 3m de lado; Reflexos CD 25 reduz à metade. Ativada por peso: qualquer criatura maior que Pequena, ou Pequena com mais de 4 espaços de equipamento.","res":["refl",25,"metade"],"dano":"8d6[impacto]","ic":"icons/svg/falling.svg"},"runa":{"nome":"Runa de Proteção","onde":"Corredores para o Salão Principal (Nível 1)","nd":2,"det":"Investigação 25","des":"Ladinagem 25","efeito":"6d6 de eletricidade em todas as criaturas a até 3m; Reflexos CD 20 reduz à metade (quem ativou não tem direito ao teste). Só detecta criaturas vivas; os mecanículos não a ativam.","res":["refl",20,"metade"],"dano":"6d6[eletricidade]","ativador":true,"ic":"icons/svg/lightning.svg"},"fossoTriplo":{"nome":"Fosso Triplo","onde":"Nível 1, Sala 15 (Antessala do Salão Principal)","nd":4,"det":"Investigação 20","des":"Ladinagem 20","efeito":"Queda de 18m: 12d6 de impacto; Reflexos CD 20 evita. Para escalar de volta: três sucessos seguidos em Atletismo CD 20. Quem cai chega ao Nível 3 (Sala 3). Detectar a armadilha pode revelar que o fosso é uma passagem para o nível mais fundo.","res":["refl",20,"evita"],"dano":"12d6[impacto]","cai":true,"ic":"icons/svg/falling.svg"},"gas":{"nome":"Gás Venenoso","onde":"Nível 1, Sala 15 (o baú entreaberto)","nd":3,"det":"Investigação 25","des":"Ladinagem 25","efeito":"Perda de 1d12 PV por veneno por rodada durante 2d4 rodadas; Fortitude CD 20 reduz à metade. O ouro do baú é ilusão (Vontade CD 18 para notar).","res":["fort",20,"metadePerda"],"perda":"1d12","rodadas":"2d4","ic":"icons/svg/poison.svg"},"afogamento":{"nome":"Sala Alagada (Armadilha de Afogamento)","onde":"Nível 2, Sala 4","nd":3,"det":"Investigação 25","des":"Ladinagem 25","ruido":3,"efeito":"Uma rodada depois que o primeiro entra, a porta de ferro se fecha e a sala se enche em 1d4 rodadas. Depois disso: prender o fôlego (1 + Con rodadas, então Fortitude CD 15 +1 por teste; falha = inconsciente e perde 1d6 PV por rodada). Lutar lá dentro: –5 em testes de For, Des e Con e na Defesa; magia em condição ruim. A porta abre depois de uma hora e há 1d4 rodadas até rearmar. Ativada ao passar pela porta (mecanismo mágico).","agua":true,"ic":"systems/tormenta20/icons/magias/controlar-agua.webp"},"fossoProfundo":{"nome":"Fosso Profundo","onde":"Nível 2, Sala 5 (Área Desabada)","nd":"1/2","det":"Investigação 20","des":"Ladinagem 20","efeito":"Queda de 6m: 4d6 de impacto; Reflexos CD 20 evita. Atletismo CD 20 para escalar de volta.","res":["refl",20,"evita"],"dano":"4d6[impacto]","cai":true,"ic":"icons/svg/falling.svg"},"executora":{"nome":"Estátua Executora","onde":"Nível 2, Sala 8 (Sala de Reparos Arruinada)","nd":3,"det":"Investigação 20","des":"Ladinagem 20","efeito":"1d12+10 mais 1d12+10 de impacto (esmagamento); dois testes de Reflexos CD 25, cada um evita um dos danos.","res":["refl",25,"dois"],"dano":"1d12+10[impacto]","ic":"systems/tormenta20/icons/ameacas/golem-de-ferro.png"},"simbolo":{"nome":"Símbolo do Atordoamento","onde":"Nível 2, Sala 12 (tampa do baú da Escadaria)","nd":5,"det":"Investigação 30","des":"Ladinagem 30","efeito":"Criaturas em alcance curto ficam atordoadas por 1d6 rodadas; Fortitude CD 25 evita. Com o grupo atordoado, as duas estátuas atacam um a um até todos morrerem.","res":["fort",25,"evita"],"status":"atordoado","rodadasStatus":"1d6","ic":"icons/svg/daze.svg"},"desabamento":{"nome":"Desabamento do Teto","onde":"Escadaria das Salas 8/9 para o Altar Mecânico (Nível 2)","nd":6,"det":"Investigação 25","des":"Ladinagem 25","ruido":5,"efeito":"15d6 de impacto em todas as criaturas numa área de 6m. O teto cai em três fases (uma por degrau): um teste de Iniciativa CD 20 por fase para escapar. Quem falha nos três faz Reflexos CD 30 para reduzir à metade.","res":["refl",30,"metade"],"dano":"15d6[impacto]","fases":true,"ic":"icons/svg/falling.svg"}},"pericias":{"sobr":"Sobrevivência","conh":"Conhecimento","perc":"Percepção","inve":"Investigação","ofic":"Ofício","reli":"Religião","mist":"Misticismo","guer":"Guerra","ades":"Adestramento","atle":"Atletismo","dipl":"Diplomacia","nobr":"Nobreza","furt":"Furtividade","cura":"Cura","intu":"Intuição","acro":"Acrobacia","ladi":"Ladinagem","vont":"Vontade","fort":"Fortitude","refl":"Reflexos","inic":"Iniciativa","luta":"Luta","for":"Força"}};
(async function macroArmadilhas(D) {
		const alvos = [...(game.user.targets.size ? game.user.targets : canvas.tokens.controlled)].filter((t) => t.actor);
		const opArm = Object.entries(D.armadilhas).map(([k, a]) => `<option value="${k}">${a.nome} (ND ${a.nd})</option>`).join("");
		const opAtiv = `<option value="">ninguém / não se aplica</option>` + alvos.map((t) => `<option value="${t.id}">${t.name}</option>`).join("");
		const res = await foundry.applications.api.DialogV2.prompt({
			window: { title: "Templo do Vácuo · Armadilhas" },
			position: { width: 480 },
			content: `
				<div class="form-group"><label>Armadilha</label><select name="arm">${opArm}</select></div>
				<div class="form-group"><label>Quem ativou (Runa: sem teste)</label><select name="ativ">${opAtiv}</select></div>
				<div class="form-group"><label>Perda de PV de uma vez (fora de combate)</label><input type="checkbox" name="deUmaVez" checked></div>
				<p style="font-size:0.85em">${alvos.length ? `Alvos: ${alvos.map((t) => t.name).join(", ")}.` : "<b>Mire ou selecione</b> os tokens atingidos."} Dano com RD aplicado sozinho; perda de PV ignora RD.</p>`,
			ok: { label: "Disparar", callback: (ev, button) => Object.fromEntries(new FormData(button.form)) }
		});
		if (!res) return;
		const a = D.armadilhas[res.arm];
		if (!alvos.length) return ui.notifications.warn("Mire ou selecione os tokens atingidos.");
		const rolls = [];
		const teste = async (actor, k, mod = 0) => {
			const r = await new Roll(`1d20 + ${Number(actor.system.pericias?.[k]?.value) || 0} + ${mod}`).evaluate();
			rolls.push(r);
			return r.total;
		};
		const perder = async (actor, n) => actor.update({ "system.attributes.pv.value": actor.system.attributes.pv.value - n });
		let html = `<h3>${a.nome}</h3><p>${a.efeito}</p><ul>`;
		if (a.agua) {
			const r = await new Roll("1d4").evaluate();
			rolls.push(r);
			html += `<li>A porta de ferro se fecha e a sala se enche em <b>${r.total} rodada(s)</b>. Depois disso, use <i>Testes do Templo › Prender o fôlego</i> a cada rodada.</li>`;
		}
		let danoComum = null;
		if (a.dano && a.res?.[2] !== "dois") { danoComum = await new Roll(a.dano).evaluate(); rolls.push(danoComum); html += `<li>Dano: <b>${danoComum.total}</b></li>`; }
		for (const t of alvos) {
			const ator = t.actor;
			const nome = t.name;
			if (a.agua) continue;
			if (a.fases) {
				let escapou = false;
				const notas = [];
				for (let f = 1; f <= 3 && !escapou; f++) {
					const v = await teste(ator, "inic");
					notas.push(v);
					if (v >= 20) escapou = true;
				}
				if (escapou) { html += `<li>${nome}: Iniciativa ${notas.join(", ")} → escapa do desabamento ✔️</li>`; continue; }
				const v = await teste(ator, "refl");
				const ok = v >= 30;
				await ator.applyDamageV2(danoComum, ok ? 0.5 : 1);
				html += `<li>${nome}: falhou nas três fases (${notas.join(", ")}); Reflexos ${v} ${ok ? "✔️ metade" : "❌ dano total"}</li>`;
				continue;
			}
			if (a.res?.[2] === "dois") {
				let txt = "";
				for (let g = 1; g <= 2; g++) {
					const v = await teste(ator, "refl");
					if (v >= a.res[1]) { txt += ` golpe ${g}: Reflexos ${v} ✔️;`; continue; }
					const d = await new Roll(a.dano).evaluate();
					rolls.push(d);
					await ator.applyDamageV2(d, 1);
					txt += ` golpe ${g}: Reflexos ${v} ❌ ${d.total};`;
				}
				html += `<li>${nome}:${txt}</li>`;
				continue;
			}
			const semTeste = a.ativador && res.ativ === t.id;
			const [k, cd, modo] = a.res ?? [];
			const v = semTeste || !k ? null : await teste(ator, k);
			const ok = v !== null && v >= cd;
			const rotulo = semTeste ? "ativou (sem teste)" : `${D.pericias[k]} ${v}`;
			if (a.perda) {
				const rodadasDado = await new Roll(String(a.rodadas)).evaluate();
				let rodadas = rodadasDado.total;
				if (modo === "uma" && ok) rodadas = 1;
				const meia = modo === "metadePerda" && ok;
				if (res.deUmaVez) {
					const p = await new Roll(`${rodadas}${a.perda.replace(/^\d+/, "")}`).evaluate();
					rolls.push(p);
					const total = meia ? Math.floor(p.total / 2) : p.total;
					await perder(ator, total);
					html += `<li>${nome}: ${rotulo} ${ok ? "✔️" : "❌"} → perde <b>${total} PV</b> (${rodadas} rodada(s)${meia ? ", metade" : ""}).</li>`;
				} else {
					await ator.createEmbeddedDocuments("ActiveEffect", [{
						name: `${a.nome}${meia ? " (metade)" : ""}`,
						img: a.ic,
						type: "base",
						duration: { value: rodadas, units: "rounds" },
						description: `Perda de ${meia ? "1d6 (metade de 1d12)" : a.perda} PV por rodada, por ${rodadas} rodada(s). Veneno.`,
						flags: { world: { fdt: "a1templo" } },
						system: { changes: [{ key: "danoContinuo", value: meia ? "1d6[perda]" : `${a.perda}[perda]`, type: "custom", phase: "initial", priority: null }] }
					}]);
					html += `<li>${nome}: ${rotulo} ${ok ? "✔️" : "❌"} → perde ${a.perda}${meia ? " (metade)" : ""} PV por rodada, por <b>${rodadas}</b> rodada(s) (efeito criado).</li>`;
				}
				continue;
			}
			if (a.status) {
				if (ok) { html += `<li>${nome}: ${rotulo} ✔️ resiste</li>`; continue; }
				const r = await new Roll(a.rodadasStatus).evaluate();
				rolls.push(r);
				await ator.toggleStatusEffect(a.status, { active: true });
				html += `<li>${nome}: ${rotulo} ❌ <b>${a.status}</b> por ${r.total} rodada(s)</li>`;
				continue;
			}
			const mult = modo === "evita" ? (ok ? 0 : 1) : (ok ? 0.5 : 1);
			if (mult > 0) await ator.applyDamageV2(danoComum, mult);
			if (a.cai && mult > 0) await ator.toggleStatusEffect("caido", { active: true });
			html += `<li>${nome}: ${rotulo} ${ok ? (modo === "evita" ? "✔️ evita" : "✔️ metade") : "❌ dano total"}${a.cai && mult > 0 ? ", cai no fosso" : ""}</li>`;
		}
		html += "</ul>";
		if (a.ruido) html += `<p><b>Ruído ${a.ruido}</b>: alerta a ${9 * a.ruido}m.</p>`;
		ChatMessage.create({ content: html, rolls });
	})(DADOS);
